    };

    // Final catch-all fallback to the bridge.
    let fallback_rule = if seen_tags.contains("grpc-bridge") {
        String::from(
            r#",
      {
        "type": "field",
        "inboundTag": ["op-tls", "ghostbridge-reality"],
        "outboundTag": "to-grpc-bridge"
      }"#,
