        profile = nextdns_profile,
        uuid = uuid,
        private_key = private_key,
        short_id = short_id,
        route_outbounds = route_outbounds,
        fallback_outbound = fallback_outbound,
        route_rules = route_rules,
        fallback_rule = fallback_rule,
        tls_certs = tls_certs,
        bridge_port = GRPC_BRIDGE_PORT,
    );

    config
}

